producing 404s. Absolute paths\nwork regardless of trailing-slash behavior.","tree":{"sha":"c08e5b8ef2fda79e5bfacf34ad5318365b675c7c","url":"https://api.github.com/repos/mohsalsaleem/salmo/git/trees/c08e5b8ef2fda79e5bfacf34ad5318365b675c7c"},"url":"https://api.github.com/repos/mohsalsaleem/salmo/git/commits/f532014339e9bd1c9f2f6078a2efd209a63fab9a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"html_url":"https://github.com/mohsalsaleem/salmo/commit/f532014339e9bd1c9f2f6078a2efd209a63fab9a","node_id":"C_kwDOSorhyNoAKGY1MzIwMTQzMzllOWJkMWM5ZjJmNjA3OGEyZWZkMjA5YTYzZmFiOWE","parents":[{"html_url":"https://github.com/mohsalsaleem/salmo/commit/11c100ada923c126f6ce70cd95c143177a4561ba","sha":"11c100ada923c126f6ce70cd95c143177a4561ba","url":"https://api.github.com/repos/mohsalsaleem/salmo/commits/11c100ada923c126f6ce70cd95c143177a4561ba"}],"sha":"f532014339e9bd1c9f2f6078a2efd209a63fab9a","url":"https://api.github.com/repos/mohsalsaleem/salmo/commits/f532014339e9bd1c9f2f6078a2efd209a63fab9a"},{"author":{"avatar_url":"htt